const productsRaw = [
    require('./56'),
    require('./58'),
    require('./59'),
    require('./61'),
    require('./62'),
    require('./78'),
    require('./80'),
    require('./94'),
    require('./141'),
    require('./165'),
    require('./170'),
    require('./172'),
    require('./177'),
];

const products = {};
productsRaw.forEach((product) => {
    if (products[product.code]) { throw new Error('Duplicate product code ' + product.code); }
    products[product.code] = product;
});

const productAbbreviations = productsRaw.map((product) => product.abbreviation).flat();

module.exports = { products, productAbbreviations, productsRaw };
